import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, mkdir, writeFile, readFile, rm, access } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { generateFoundation } from '../src/config.mjs';

/** A temporary Next project: the `next` dependency selects the Next provider in the generated file. */
async function fixture(run, { next = true } = {}) {
  const root = await mkdtemp(path.join(tmpdir(), 'bitakit-next-'));
  async function put(file, text) {
    const target = path.join(root, file);
    await mkdir(path.dirname(target), { recursive: true });
    await writeFile(target, text);
  }
  if (next)
    await put(
      'package.json',
      JSON.stringify({ name: 'host', type: 'module', dependencies: { next: '16.0.0' } }),
    );
  const output = () =>
    readFile(path.join(root, next ? 'src/bitakit.gen.tsx' : 'src/bitakit.gen.ts'), 'utf8');
  const generate = () => generateFoundation(root, { quiet: true });
  const exists = (file) =>
    access(path.join(root, file)).then(
      () => true,
      () => false,
    );
  try {
    await run({ root, put, output, generate, exists });
  } finally {
    await rm(root, { recursive: true, force: true });
  }
}

test('discovers folder conventions without executing files and writes the typed Next entry point', async () =>
  fixture(async ({ root, put, output, generate, exists }) => {
    await put('bitakit.config.ts', "export default { groups: ['menu'] }");
    await put(
      'src/plugins/users/actions/invite.ts',
      "throw new Error('Must not execute'); export default {};",
    );
    await put('src/plugins/users/actions/team/promote.ts', 'export default {};');
    await put('src/plugins/users/services/directory.ts', 'export default {};');
    await put('src/plugins/users/events.ts', 'export default {};');
    await put('src/plugins/users/configs/limits.ts', 'export default {};');
    await put('src/plugins/users/setup.ts', 'export default () => {};');
    await put('src/plugins/users/locales/de.json', '{"users":{"title":"Benutzer"}}');
    await put('src/plugins/users/server/secret.ts', 'export default {};');
    await put('src/plugins/users/ui/components/avatar.tsx', 'export default () => null;');
    const result = await generate();
    assert.equal(result.framework, 'next');
    assert.equal(result.generated, path.join(await realRoot(root), 'src/bitakit.gen.tsx'));
    assert.deepEqual(result.warnings, []);
    const code = await output();
    assert.match(code, /^\/\/ Generated by BitaKit\. Do not edit\.\n'use client';/);
    assert.match(code, /import entry\d+ from '\.\/plugins\/users\/actions\/invite';/);
    assert.match(
      code,
      /discoveredFile\(entry\d+, "invite", "src\/plugins\/users\/actions\/invite\.ts"\)/,
    );
    assert.match(
      code,
      /discoveredFile\(entry\d+, "team\.promote", "src\/plugins\/users\/actions\/team\/promote\.ts"\)/,
    );
    assert.match(code, /actions: discoverActions\(\[file\d+, file\d+\], "users"\)/);
    assert.match(code, /services: discoverServices\(\[file\d+\], "users"\)/);
    assert.match(code, /events: discoverEvents\(\[file\d+\]\)/);
    assert.match(code, /config: discoverConfig\(\[file\d+\]\)/);
    assert.match(code, /setup: entry\d+,/);
    assert.match(code, /DiscoveredActionEntry<typeof file\d+, "users">/);
    assert.match(code, /DiscoveredServiceEntry<typeof file\d+, "users">/);
    assert.match(code, /DiscoveredEventsEntry<typeof file\d+, "users">/);
    assert.match(code, /"users": DiscoveredConfigEntry<typeof file\d+>;/);
    assert.match(code, /interface ActionMap extends DiscoveredActions/);
    assert.match(code, /interface ServiceMap extends DiscoveredServices, InstalledServices/);
    assert.match(code, /interface ActionMapOptions \{ strict: true \}/);
    assert.match(code, /groups: \["menu"\]/);
    assert.match(code, /export function createBitaKitConfig\(\)/);
    assert.match(code, /import \{ FoundationProvider \} from '@bitakit\/next';/);
    assert.match(
      code,
      /export function BitaKitProvider\(props: Omit<ComponentProps<typeof FoundationProvider>, 'config'>\)/,
    );
    assert.match(code, /<FoundationProvider \{\.\.\.props\} config=\{config\} \/>/);
    assert.doesNotMatch(
      code,
      /server\/secret|ui\/components\/avatar/,
      'server files and plain components are never contributions',
    );
    assert.doesNotMatch(
      code,
      /@bitakit\/next\/generated|\.foundation\//,
      'no alias target remains',
    );
    assert.deepEqual(
      JSON.parse(await readFile(path.join(root, 'src/bitakit.gen.messages.json'), 'utf8')),
      { de: { users: { title: 'Benutzer' } } },
    );
    assert.match(
      await readFile(path.join(root, 'src/bitakit.gen.css'), 'utf8'),
      /Generated by BitaKit/,
    );
    assert.equal(
      await exists('src/bitakit.gen.ts'),
      false,
      'only one entry file extension exists at a time',
    );
    await put(
      'bitakit.config.ts',
      'export default { plugins: { overrides: { users: { enabled: false } } } }',
    );
    await generate();
    assert.doesNotMatch(await output(), /actions\/invite/);
    assert.equal(
      await exists('src/bitakit.gen.messages.json'),
      false,
      'locales of disabled plugins are not emitted',
    );
  }));

test('a project without Next gets a plain .ts entry without a provider; the other extension is cleaned up', async () =>
  fixture(
    async ({ put, output, generate, exists }) => {
      await put('src/actions/ping.ts', 'export default {};');
      const result = await generate();
      assert.equal(result.framework, 'none');
      const code = await output();
      assert.doesNotMatch(code, /'use client'|BitaKitProvider|@bitakit\/next/);
      assert.match(
        code,
        /actions: discoverActions\(\[file\d+\], ""\)/,
        'app actions are not prefixed',
      );
      await put('package.json', JSON.stringify({ dependencies: { next: '16.0.0' } }));
      assert.equal((await generate()).framework, 'next');
      assert.equal(await exists('src/bitakit.gen.tsx'), true);
      assert.equal(await exists('src/bitakit.gen.ts'), false);
      await put('bitakit.config.ts', "export default { framework: 'none' }");
      assert.equal((await generate()).framework, 'none');
      assert.equal(await exists('src/bitakit.gen.tsx'), false);
    },
    { next: false },
  ));

test('legacy locations and suffixes still work and are reported as warnings', async () =>
  fixture(async ({ put, output, generate }) => {
    await put('bitakit.config.ts', "export default { plugins: { directory: 'plugins' } }");
    await put('plugins/users/plugin.config.ts', "export default { id: 'users' }");
    await put(
      'plugins/users/actions/invite.form-action.ts',
      "throw new Error('Must not execute'); export default {};",
    );
    await put('plugins/users/services/users.service.ts', 'export default {}');
    await put('plugins/users/pages/details.page.tsx', 'export default {};');
    await put('plugins/users/views/app-bar.end.view.tsx', 'export default {};');
    await put('plugins/users/actions/helpers.ts', 'export const helper = true;');
    await put('plugins/users/actions/-shared.ts', 'export default {};');
    const { warnings } = await generate();
    const code = await output();
    assert.match(
      code,
      /discoveredFile\(entry\d+, "invite", "plugins\/users\/actions\/invite\.form-action\.ts"\)/,
      'suffixes are stripped from the ID',
    );
    assert.match(
      code,
      /discoveredFile\(entry\d+, "users", "plugins\/users\/services\/users\.service\.ts"\)/,
    );
    assert.match(code, /pluginPage\(module\d+, "\/users\/details"\)/);
    assert.match(code, /pluginSlot\(module\d+, "app-bar\.end"\)/);
    assert.doesNotMatch(
      code,
      /helpers|-shared/,
      'files without a default export and "-" helpers are not contributions',
    );
    assert.ok(
      warnings.some((warning) =>
        /invite\.form-action\.ts: drop the "\.form-action" suffix/.test(warning),
      ),
    );
    assert.ok(
      warnings.some((warning) =>
        /pages\/details\.page\.tsx: move it under ui\/pages\//.test(warning),
      ),
    );
    assert.ok(
      warnings.some((warning) =>
        /views\/app-bar\.end\.view\.tsx: move it under ui\/slots\//.test(warning),
      ),
    );
    assert.ok(
      warnings.some((warning) =>
        /actions\/helpers\.ts is in a actions folder but has no default export/.test(warning),
      ),
    );
    assert.equal(
      warnings.some((warning) => /-shared/.test(warning)),
      false,
      'helpers prefixed with "-" are skipped silently',
    );
  }));

test('plugin manifests override entry folders, and a missing explicit entry is an error', async () =>
  fixture(async ({ put, output, generate }) => {
    await put(
      'src/plugins/users/plugin.config.ts',
      "export default { id: 'people', dependencies: ['shell'], entries: { actions: 'commands' } }",
    );
    await put('src/plugins/users/commands/create.ts', 'export default {}');
    await put('src/plugins/users/actions/ignored.ts', 'export default {}');
    await put('src/plugins/shell/actions/open.ts', 'export default {}');
    await generate();
    const code = await output();
    assert.match(code, /id: "people", metadata: \{\}, dependencies: \["shell"\]/);
    assert.match(
      code,
      /discoveredFile\(entry\d+, "create", "src\/plugins\/users\/commands\/create\.ts"\)/,
    );
    assert.doesNotMatch(
      code,
      /actions\/ignored/,
      'an explicit entry folder replaces the convention',
    );
    await put(
      'src/plugins/users/plugin.config.ts',
      "export default { id: 'people', entries: { actions: 'missing' } }",
    );
    await assert.rejects(generate(), /Plugin "people" names a missing entry for "actions"/);
    await put('src/plugins/users/plugin.config.ts', "export default { id: 'Bad Id' }");
    await assert.rejects(generate(), /Invalid plugin ID "Bad Id"/);
  }));

test('app contributions need no manifest; add, rename and delete update the imports', async () =>
  fixture(async ({ root, put, output, generate }) => {
    await put('bitakit.config.ts', "export default { actions: { directory: 'commands' } }");
    await put(
      'commands/account/logout.ts',
      "throw new Error('Discovery must not run code'); export default {};",
    );
    await put('src/services/clock.ts', 'export default {};');
    await put('src/events.ts', 'export default {};');
    await generate();
    assert.match(await output(), /import entry\d+ from '\.\.\/commands\/account\/logout';/);
    assert.match(
      await output(),
      /discoveredFile\(entry\d+, "account\.logout", "commands\/account\/logout\.ts"\)/,
    );
    assert.match(await output(), /services: discoverServices\(\[file\d+\], ""\)/);
    assert.match(await output(), /events: discoverEvents\(\[file\d+\]\)/);
    assert.match(await output(), /DiscoveredEventsEntry<typeof file\d+, "app">/);
    await rm(path.join(root, 'commands/account/logout.ts'));
    await put('commands/account/invite.ts', 'export default {};');
    await generate();
    assert.doesNotMatch(await output(), /logout/);
    assert.match(await output(), /account\.invite/);
    await put('bitakit.config.ts', 'export default { actions: false }');
    await generate();
    assert.doesNotMatch(await output(), /account\.invite/);
    assert.match(await output(), /actions: discoverActions\(\[\], ""\)/);
  }));

test('the watcher regenerates on new and deleted files without restarting', async () =>
  fixture(
    async ({ root, put, output, generate }) => {
      const { watchFoundation } = await import('@bitakit/discovery');
      await generate();
      const errors = [];
      const stop = watchFoundation(root, (error) => errors.push(error));
      async function until(predicate) {
        const end = Date.now() + 5000;
        while (Date.now() < end) {
          if (await predicate()) return;
          await new Promise((resolve) => setTimeout(resolve, 30));
        }
        assert.fail('Discovery did not update within five seconds');
      }
      try {
        await put('src/actions/new.ts', 'export default {};');
        await until(async () => (await output()).includes('actions/new'));
        await rm(path.join(root, 'src/actions/new.ts'));
        await until(async () => !(await output()).includes('actions/new'));
        assert.deepEqual(errors, []);
      } finally {
        stop();
      }
    },
    { next: false },
  ));

test('interceptors are enabled explicitly in config order; unknown names and duplicates fail', async () =>
  fixture(async ({ put, output, generate }) => {
    await put(
      'bitakit.config.ts',
      "export default { actions: { overrides: { 'account.logout': { enabled: false } } }, interceptors: { enabled: ['guard', 'confirm'] } }",
    );
    await put(
      'src/interceptors/confirm.ts',
      "throw new Error('Do not execute during discovery'); export default {};",
    );
    await put('src/interceptors/guard.ts', 'export default {};');
    await put('src/interceptors/unused.ts', 'export default {};');
    await generate();
    const code = await output();
    assert.ok(code.indexOf('interceptors/guard') < code.indexOf('interceptors/confirm'));
    assert.doesNotMatch(code, /interceptors\/unused/);
    assert.match(code, /actionOverrides: \{"account\.logout":\{"enabled":false\}\}/);
    await put('bitakit.config.ts', "export default { interceptors: { enabled: ['missing'] } }");
    await assert.rejects(
      generate(),
      /interceptors\.enabled names "missing", but no interceptor file with that name exists/,
    );
    await put(
      'bitakit.config.ts',
      "export default { interceptors: { enabled: ['guard', 'guard'] } }",
    );
    await assert.rejects(generate(), /listed twice/);
  }));

test('ui/providers are included by default; a legacy providers folder needs the enabled list', async () =>
  fixture(async ({ put, output, generate }) => {
    await put(
      'src/ui/providers/theme.tsx',
      "throw new Error('Do not evaluate'); export default {};",
    );
    await put('src/ui/providers/query.tsx', 'export default {};');
    await put('src/plugins/widgets/ui/providers/store.tsx', 'export default {};');
    await generate();
    let code = await output();
    assert.match(code, /pluginProvider\(module\d+, "query"\)/);
    assert.match(code, /pluginProvider\(module\d+, "theme"\)/);
    assert.match(
      code,
      /pluginProvider\(module\d+, "widgets\.store"\)/,
      'plugin providers are namespaced',
    );
    assert.match(
      code,
      /import \* as module\d+ from '\.\/ui\/providers\/theme';/,
      'UI modules are imported as namespaces so layout and requires travel along',
    );
    await put(
      'bitakit.config.ts',
      "export default { providers: { directory: 'wrappers', enabled: ['theme', 'widgets'] } }",
    );
    await put('wrappers/theme.tsx', 'export default {};');
    await put('wrappers/widgets.tsx', 'export default {};');
    await put('wrappers/unused.tsx', 'export default {};');
    await generate();
    code = await output();
    assert.ok(code.indexOf('wrappers/theme') < code.indexOf('wrappers/widgets'));
    assert.doesNotMatch(code, /wrappers\/unused/);
    await put(
      'bitakit.config.ts',
      "export default { providers: { directory: 'wrappers', enabled: ['missing'] } }",
    );
    await assert.rejects(generate(), /providers\.enabled names "missing"/);
  }));

test('pages take their path from the file name, including index and [id] segments', async () =>
  fixture(async ({ put, output, generate }) => {
    await put(
      'src/plugins/demo/ui/pages/index.tsx',
      "throw new Error('Do not evaluate'); export default {};",
    );
    await put('src/plugins/demo/ui/pages/tasks/[id].tsx', 'export default {};');
    await put('src/plugins/demo/ui/pages/settings/index.tsx', 'export default {};');
    await put('src/plugins/demo/ui/slots/app-bar.end.tsx', 'export default {};');
    await put('src/ui/pages/index.tsx', 'export default {};');
    await put('src/ui/pages/about.tsx', 'export default {};');
    await generate();
    const code = await output();
    assert.match(code, /pluginPage\(module\d+, "\/demo"\)/);
    assert.match(code, /pluginPage\(module\d+, "\/demo\/tasks\/\[id\]"\)/);
    assert.match(code, /pluginPage\(module\d+, "\/demo\/settings"\)/);
    assert.match(code, /pluginSlot\(module\d+, "app-bar\.end"\)/);
    assert.match(code, /pluginPage\(module\d+, "\/"\)/, 'the app index page is the root');
    assert.match(code, /pluginPage\(module\d+, "\/about"\)/);
    await put(
      'bitakit.config.ts',
      'export default { plugins: { overrides: { demo: { enabled: false } } } }',
    );
    await generate();
    assert.doesNotMatch(await output(), /demo\/ui\/pages/);
  }));

test('plugin metadata uses package fields, supports local overrides and excludes private configuration', async () =>
  fixture(async ({ put, output, generate }) => {
    await put(
      'src/plugins/example/plugin.config.ts',
      "export default { id: 'example', metadata: { description: 'Local description' } };",
    );
    await put(
      'src/plugins/example/package.json',
      JSON.stringify({
        name: '@demo/example',
        version: '1.2.0',
        author: 'Example',
        description: 'Package description',
        scripts: { secret: 'never-public' },
      }),
    );
    await put('src/plugins/example/actions/run.ts', 'export default {};');
    await generate();
    const code = await output();
    assert.match(code, /"name":"@demo\/example","version":"1\.2\.0"/);
    assert.match(code, /"description":"Local description"/);
    assert.match(code, /"author":"Example"/);
    assert.doesNotMatch(code, /never-public|Package description/);
  }));

test('plugins included from outside the project are generated and reported for the bundler', async () =>
  fixture(async ({ root, put, output, generate }) => {
    const external = path.join(root, '..', `bitakit-external-${path.basename(root)}`);
    try {
      await mkdir(path.join(external, 'actions'), { recursive: true });
      await writeFile(path.join(external, 'actions', 'open.ts'), 'export default {};');
      await writeFile(
        path.join(external, 'package.json'),
        JSON.stringify({ name: 'notes-plugin', version: '0.1.0' }),
      );
      await put(
        'bitakit.config.ts',
        `export default { plugins: { include: { notes: ${JSON.stringify(external)} } } }`,
      );
      const result = await generate();
      assert.deepEqual(result.included, [external]);
      const code = await output();
      assert.match(code, /id: "notes", metadata: \{"name":"notes-plugin","version":"0\.1\.0"\}/);
      assert.match(code, /actions: discoverActions\(\[file\d+\], "notes"\)/);
      await put(
        'bitakit.config.ts',
        "export default { plugins: { include: { 'Bad Id': '../x' } } }",
      );
      await assert.rejects(generate(), /Invalid included plugin ID "Bad Id"/);
    } finally {
      await rm(external, { recursive: true, force: true });
    }
  }));

test('duplicate plugin IDs and misplaced locale namespaces fail with the offending file named', async () =>
  fixture(async ({ put, generate }) => {
    await put('src/plugins/one/plugin.config.ts', "export default { id: 'shared' }");
    await put('src/plugins/two/plugin.config.ts', "export default { id: 'shared' }");
    await assert.rejects(generate(), /Plugin ID "shared" is used twice/);
    await put('src/plugins/two/plugin.config.ts', "export default { id: 'two' }");
    await put('src/plugins/two/locales/en.json', '{"other":{"title":"Wrong namespace"}}');
    await assert.rejects(
      generate(),
      /src\/plugins\/two\/locales\/en\.json: locale keys must sit under the plugin namespace "two"/,
    );
  }));

async function realRoot(root) {
  const { realpath } = await import('node:fs/promises');
  return realpath(root);
}
